var sanitizeRe = regexp.MustCompile(`[^a-zA-Z0-9_-]+`)

func writePprofHeap(label string) {
	ts := time.Now().Format("20060102-150405")
	args := sanitizeRe.ReplaceAllString(strings.Join(os.Args[1:], "_"), "_")
	if args == "" {
		args = "noargs"
	}
	filename := fmt.Sprintf("/tmp/entire-pprof-%s-%s-%s.pb.gz", ts, args, label)
	f, err := os.Create(filename)
	if err != nil {
		fmt.Fprintf(os.Stderr, "pprof: failed to create %s: %v\n", filename, err)
		return
	}
	defer f.Close()
	if err := pprof.WriteHeapProfile(f); err != nil {
		fmt.Fprintf(os.Stderr, "pprof: failed to write %s: %v\n", filename, err)
	}
}

func main() {
	writePprofHeap("start")

	// Create context that cancels on interrupt
	ctx, cancel := context.WithCancel(context.Background())

	// Handle interrupt signals
	sigChan := make(chan os.Signal, 1)
	signal.Notify(sigChan, os.Interrupt, syscall.SIGTERM)
	go func() {
		<-sigChan
		cancel()
	}()

	// Create and execute root command
	rootCmd := cli.NewRootCmd()
	err := rootCmd.ExecuteContext(ctx)

	writePprofHeap("end")
